-- Jóváhagyott PDF 18/19/25. Csak saját ERP-objektumok; forrásalkalmazáshoz nincs írás.
begin;
create table erp.calendar_settings(
 organization_id uuid primary key references erp.organizations(id),revision bigint not null default 0,
 document jsonb not null default '{"office":true,"roles":{},"booking":false,"date_requests":false,"windows":[],"capacity":0}',updated_by uuid,updated_at timestamptz not null default now(),
 foreign key(organization_id,updated_by) references erp.persons(organization_id,id));
create table erp.calendar_catalog(
 organization_id uuid not null references erp.organizations(id),kind text not null check(kind in('workers','vehicles','tools','materials','templates','recurrences')),id text not null check(length(id) between 1 and 120),revision bigint not null default 1,
 document jsonb not null check(jsonb_typeof(document)='object'),person_id uuid,source_kind text not null default 'erp',source_hash text,edited boolean not null default true,active boolean not null default true,
 primary key(organization_id,kind,id),foreign key(organization_id,person_id) references erp.persons(organization_id,id),check(person_id is null or kind='workers'));
create index calendar_catalog_person on erp.calendar_catalog(organization_id,person_id) where person_id is not null;
create table erp.daily_plans(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references erp.organizations(id),day date not null,version bigint not null default 0,state text not null default 'active' check(state in('active','withdrawn')),edited boolean not null default true,source_hash text,source_owner uuid,source_conflict boolean not null default false,updated_at timestamptz not null default now(),
 unique(organization_id,day),unique(organization_id,id));
create table erp.daily_plan_versions(
 organization_id uuid not null,plan_id uuid not null,version bigint not null,document jsonb not null check(jsonb_typeof(document)='object'),actor_id uuid not null,kind text not null,created_at timestamptz not null default now(),
 primary key(plan_id,version),unique(organization_id,plan_id,version),foreign key(organization_id,plan_id) references erp.daily_plans(organization_id,id),foreign key(organization_id,actor_id) references erp.persons(organization_id,id));
create index daily_versions_actor on erp.daily_plan_versions(organization_id,actor_id);
create table erp.calendar_slots(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references erp.organizations(id),plan_id uuid,task_id text,booking_id uuid,project_id uuid,day date not null,start_at timestamptz,end_at timestamptz,workers text[] not null default '{}',vehicles text[] not null default '{}',headcount integer not null check(headcount>=0),padding integer not null default 0 check(padding in(0,60)),uncertain boolean not null default false,active boolean not null default true,
 foreign key(organization_id,plan_id) references erp.daily_plans(organization_id,id),foreign key(organization_id,project_id) references erp.garden_projects(organization_id,id),unique(organization_id,plan_id,task_id),check(uncertain or start_at is not null and end_at>start_at));
create index calendar_slots_time on erp.calendar_slots(organization_id,day,start_at) where active;
create index calendar_slots_plan on erp.calendar_slots(organization_id,plan_id);
create index calendar_slots_project on erp.calendar_slots(organization_id,project_id);
create table erp.calendar_blocks(
 id uuid primary key,organization_id uuid not null references erp.organizations(id),revision bigint not null default 1,document jsonb not null,active boolean not null default true,actor_id uuid not null,foreign key(organization_id,actor_id) references erp.persons(organization_id,id),unique(organization_id,id));
create index calendar_blocks_org on erp.calendar_blocks(organization_id) where active;
create table erp.calendar_booking_requests(
 id uuid primary key,organization_id uuid not null references erp.organizations(id),person_id uuid not null,customer_id uuid not null,location_id uuid not null,project_id uuid,maintenance_request_id uuid,start_at timestamptz not null,end_at timestamptz not null,headcount integer not null check(headcount between 1 and 1000),state text not null default 'requested' check(state in('requested','approved','rejected','withdrawn')),revision bigint not null default 1,note text not null default '',decided_by uuid,created_at timestamptz not null default now(),
 check(end_at>start_at and end_at<=start_at+interval '7 days'),unique(organization_id,id),foreign key(organization_id,person_id) references erp.persons(organization_id,id),foreign key(organization_id,decided_by) references erp.persons(organization_id,id),foreign key(organization_id,project_id) references erp.garden_projects(organization_id,id),foreign key(organization_id,maintenance_request_id) references erp.maintenance_requests(organization_id,id));
create index calendar_booking_person on erp.calendar_booking_requests(organization_id,person_id,created_at,id);
create index calendar_booking_project on erp.calendar_booking_requests(organization_id,project_id);
create index calendar_booking_maint on erp.calendar_booking_requests(organization_id,maintenance_request_id);
create index calendar_booking_decider on erp.calendar_booking_requests(organization_id,decided_by);
alter table erp.calendar_slots add foreign key(organization_id,booking_id) references erp.calendar_booking_requests(organization_id,id);
create index calendar_slots_booking on erp.calendar_slots(organization_id,booking_id);
create table erp.calendar_events(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references erp.organizations(id),actor_id uuid not null,kind text not null,target text,version bigint,data jsonb not null default '{}',created_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,actor_id) references erp.persons(organization_id,id));
create index calendar_events_org on erp.calendar_events(organization_id,created_at,id);
create index calendar_events_actor on erp.calendar_events(organization_id,actor_id);
create table erp.calendar_notifications(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,recipient_id uuid not null,event_id uuid not null,kind text not null,target text,read_at timestamptz,created_at timestamptz not null default now(),unique(event_id,recipient_id),foreign key(organization_id,event_id) references erp.calendar_events(organization_id,id),foreign key(organization_id,recipient_id) references erp.persons(organization_id,id));
create index calendar_notifications_person on erp.calendar_notifications(organization_id,recipient_id,created_at,id);
create index calendar_notifications_event on erp.calendar_notifications(organization_id,event_id);
create table erp_private.calendar_import_runs(
 id uuid primary key,organization_id uuid not null references erp.organizations(id),actor_id uuid not null,source_owner uuid,manifest jsonb not null,source_hash text not null,state text not null check(state in('preview','applied','conflict')),created_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,actor_id) references erp.persons(organization_id,id));
create index calendar_import_actor on erp_private.calendar_import_runs(organization_id,actor_id);
create table erp_private.calendar_source_rows(
 id bigint generated always as identity primary key,organization_id uuid not null,run_id uuid not null,source_key text not null,source_hash text not null,payload jsonb not null,updated_at timestamptz,deleted boolean not null default false,
 unique(organization_id,source_key,source_hash),foreign key(organization_id,run_id) references erp_private.calendar_import_runs(organization_id,id));
create index calendar_source_run on erp_private.calendar_source_rows(organization_id,run_id);
create table erp_private.calendar_commands(
 organization_id uuid not null,request_id uuid not null,actor_id uuid not null,kind text not null,fingerprint text not null,result jsonb not null,created_at timestamptz not null default now(),primary key(organization_id,request_id),foreign key(organization_id,actor_id) references erp.persons(organization_id,id));
create index calendar_commands_actor on erp_private.calendar_commands(organization_id,actor_id);
create table erp.calendar_push_subscriptions(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,person_id uuid not null,endpoint text not null unique,document jsonb not null,enabled boolean not null default true,updated_at timestamptz not null default now(),foreign key(organization_id,person_id) references erp.persons(organization_id,id),unique(organization_id,id));
create index calendar_push_person on erp.calendar_push_subscriptions(organization_id,person_id) where enabled;
create table erp.calendar_reminders(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,plan_id uuid not null,version bigint not null,item_id text not null,person_id uuid not null,due_at timestamptz not null,event_at timestamptz not null,active boolean not null default true,created_at timestamptz not null default now(),unique(plan_id,version,item_id,person_id,due_at),unique(organization_id,id),foreign key(organization_id,plan_id,version) references erp.daily_plan_versions(organization_id,plan_id,version),foreign key(organization_id,person_id) references erp.persons(organization_id,id));
create index calendar_reminders_due on erp.calendar_reminders(due_at) where active;
create index calendar_reminders_person on erp.calendar_reminders(organization_id,person_id);
create table erp_private.calendar_reminder_deliveries(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null,reminder_id uuid not null,subscription_id uuid not null,state text not null default 'pending' check(state in('pending','sending','sent','failed','expired')),attempts integer not null default 0,next_at timestamptz not null default now(),lease_until timestamptz,updated_at timestamptz not null default now(),unique(reminder_id,subscription_id),foreign key(organization_id,reminder_id) references erp.calendar_reminders(organization_id,id),foreign key(organization_id,subscription_id) references erp.calendar_push_subscriptions(organization_id,id));
create index calendar_deliveries_ready on erp_private.calendar_reminder_deliveries(next_at) where state in('pending','failed','sending');
create index calendar_deliveries_subscription on erp_private.calendar_reminder_deliveries(organization_id,subscription_id);

create index calendar_blocks_actor on erp.calendar_blocks(organization_id,actor_id);
create index calendar_reminders_plan_version on erp.calendar_reminders(organization_id,plan_id,version);
create index calendar_settings_editor on erp.calendar_settings(organization_id,updated_by);
create index calendar_deliveries_reminder on erp_private.calendar_reminder_deliveries(organization_id,reminder_id);

create function erp_private.calendar_scope(p_org uuid,p_actor uuid,p_session uuid,p_role text) returns jsonb language plpgsql security definer set search_path='' as $$
declare person uuid;office boolean;settings jsonb;c erp_private.client_accounts;s erp_private.staff_accounts;begin
 select a.person_id into person from erp.user_accounts a join erp.persons p on p.organization_id=a.organization_id and p.id=a.person_id where a.organization_id=p_org and a.auth_user_id=p_actor and a.active and p.active;
 if person is null then raise exception 'Saját ERP-belépés szükséges.' using errcode='42501';end if;
 office:=exists(select 1 from erp.person_roles where organization_id=p_org and person_id=person and role='office' and revoked_at is null and valid_from<=now() and (valid_until is null or valid_until>now()));
 if p_role='office' then if not office then raise exception 'Irodai jogosultság szükséges.' using errcode='42501';end if;
 elsif p_role='client' then c:=erp_private.require_client_session(p_actor,p_session);if c.organization_id<>p_org then raise exception 'Idegen szervezet.' using errcode='42501';end if;
 elsif p_role in('construction_lead','maintenance_lead','construction_worker','gardener') then s:=erp_private.require_staff_session(p_actor,p_session);if s.organization_id<>p_org then raise exception 'Idegen szervezet.' using errcode='42501';end if;
 else raise exception 'Érvénytelen naptári szerep.' using errcode='42501';end if;
 select document into settings from erp.calendar_settings where organization_id=p_org;settings:=coalesce(settings,'{"office":true,"roles":{},"booking":false,"date_requests":false,"windows":[],"capacity":0}');
 if p_role in('construction_lead','maintenance_lead') and not exists(select 1 from erp.project_assignments where organization_id=p_org and person_id=person and role=p_role and revoked_at is null and valid_from<=now() and (valid_until is null or valid_until>now())) then raise exception 'Nincs ilyen vezetői megbízásod.' using errcode='42501';end if;
 if p_role<>'office' and not coalesce((settings->'roles'->>p_role)::boolean,false) then raise exception 'A naptár ezzel a szereppel nincs engedélyezve.' using errcode='42501';end if;
 if p_role='office' and not coalesce((settings->>'office')::boolean,true) then raise exception 'Az irodai naptár ki van kapcsolva.' using errcode='42501';end if;
 return jsonb_build_object('person_id',person,'role',p_role,'organization_id',p_org,'settings',settings);
end$$;
create function erp_private.calendar_office(p_org uuid,p_actor uuid,p_session uuid,p_role text) returns uuid language plpgsql security definer set search_path='' as $$declare ctx jsonb;begin
 ctx:=erp_private.calendar_scope(p_org,p_actor,p_session,p_role);if p_role<>'office' then raise exception 'Csak az iroda módosíthat naptárat.' using errcode='42501';end if;return (ctx->>'person_id')::uuid;end$$;
create function erp_private.calendar_event(p_org uuid,p_person uuid,p_kind text,p_target text,p_version bigint,p_data jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare event uuid;begin
 insert into erp.calendar_events(organization_id,actor_id,kind,target,version,data) values(p_org,p_person,p_kind,p_target,p_version,p_data) returning id into event;return event;end$$;
create function erp_private.calendar_capacity(p_org uuid,p_start timestamptz,p_end timestamptz,p_count integer,p_workers text[],p_vehicles text[],p_ignore_plan uuid default null,p_ignore_booking uuid default null) returns void language plpgsql security definer set search_path='' as $$
declare settings jsonb;v_day date;w jsonb;b record;at_day date;bs timestamptz;be timestamptz;capacity integer;point timestamptz;load integer;blocked text[]:='{}';begin
 if p_start is null or p_end is null or p_end<=p_start or p_end>p_start+interval '7 days' or p_count<0 then raise exception 'Pontos kezdés, befejezés és létszám szükséges.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('erp-calendar:'||p_org::text,0));v_day:=(p_start at time zone 'Europe/Budapest')::date;
 select document into settings from erp.calendar_settings where organization_id=p_org;capacity:=coalesce((settings->>'capacity')::integer,0);
 if capacity<=0 then raise exception 'Az iroda még nem állított be létszámkapacitást.' using errcode='22023';end if;
 if not exists(select 1 from jsonb_array_elements(coalesce(settings->'windows','[]')) x where (x->>'weekday')::integer=extract(dow from v_day)::integer and (v_day+(x->>'start')::time) at time zone 'Europe/Budapest'<=p_start and (v_day+(x->>'end')::time) at time zone 'Europe/Budapest'>=p_end) then raise exception 'Ez az időablak nincs megnyitva.' using errcode='22023';end if;
 if exists(select 1 from erp.calendar_slots s where s.organization_id=p_org and s.active and s.uncertain and s.day between v_day-1 and (p_end at time zone 'Europe/Budapest')::date+1 and (p_ignore_plan is null or s.plan_id is distinct from p_ignore_plan)) then raise exception 'Hiányzó befejezési idő miatt a szabad kapacitás nem igazolható.' using errcode='22023';end if;
 for b in select document from erp.calendar_blocks where organization_id=p_org and active loop
 for at_day in select generate_series(v_day-1,(p_end at time zone 'Europe/Budapest')::date,interval '1 day')::date loop
 if at_day between (b.document->>'start_date')::date and (b.document->>'end_date')::date and (coalesce(b.document->>'repeat','once')='once' or coalesce(b.document->'weekdays','[]')@>jsonb_build_array(extract(dow from at_day)::integer)) then
 bs:=(at_day+(b.document->>'start_time')::time) at time zone 'Europe/Budapest';be:=(at_day+(b.document->>'end_time')::time) at time zone 'Europe/Budapest';if be<=bs then be:=be+interval '1 day';end if;
 if bs<p_end and be>p_start then if jsonb_array_length(coalesce(b.document->'workers','[]'))=0 or exists(select 1 from jsonb_array_elements_text(b.document->'workers') v where v=any(p_workers)) then raise exception 'Irodai időtiltás érinti a kiválasztott időpontot.' using errcode='22023';end if;select array_agg(distinct v) into blocked from(select unnest(blocked) v union select jsonb_array_elements_text(b.document->'workers')) x;end if;end if;
 end loop;end loop;capacity:=capacity-coalesce(cardinality(blocked),0);
 if exists(select 1 from erp.calendar_slots s where s.organization_id=p_org and s.active and not s.uncertain and (p_ignore_plan is null or s.plan_id is distinct from p_ignore_plan) and (p_ignore_booking is null or s.booking_id is distinct from p_ignore_booking) and s.start_at-make_interval(mins=>s.padding)<p_end and s.end_at+make_interval(mins=>s.padding)>p_start and (s.workers&&p_workers or s.vehicles&&p_vehicles)) then raise exception 'A munkatárs vagy autó ekkor már be van osztva.' using errcode='22023';end if;
 for point in select p_start union select greatest(s.start_at-make_interval(mins=>s.padding),p_start) from erp.calendar_slots s where s.organization_id=p_org and s.active and not s.uncertain and s.start_at-make_interval(mins=>s.padding)<p_end and s.end_at+make_interval(mins=>s.padding)>p_start and (p_ignore_plan is null or s.plan_id is distinct from p_ignore_plan) and (p_ignore_booking is null or s.booking_id is distinct from p_ignore_booking) loop
 select coalesce(sum(s.headcount),0) into load from erp.calendar_slots s where s.organization_id=p_org and s.active and not s.uncertain and s.start_at-make_interval(mins=>s.padding)<=point and s.end_at+make_interval(mins=>s.padding)>point and (p_ignore_plan is null or s.plan_id is distinct from p_ignore_plan) and (p_ignore_booking is null or s.booking_id is distinct from p_ignore_booking);
 if load+p_count>capacity then raise exception 'Nincs elegendő szabad létszám a teljes időszakra.' using errcode='22023';end if;end loop;
end$$;
create function erp_private.calendar_plan_save(p_org uuid,p_person uuid,p_day date,p_revision bigint,p_doc jsonb,p_source text default null,p_source_owner uuid default null,p_force boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare h erp.daily_plans;t jsonb;k text;ref text;worker text;vehicle text;starts timestamptz;ends timestamptz;proj erp.garden_projects;pid uuid;event uuid;count_people integer;pad integer;visit erp.calendar_booking_requests;linked uuid;allworkers text[];allvehicles text[];reserved integer;begin
 perform pg_advisory_xact_lock(hashtextextended('erp-calendar:'||p_org::text,0));select * into h from erp.daily_plans where organization_id=p_org and day=p_day for update;
 if h.id is null then if p_revision<>0 then raise exception 'A napiterv megváltozott.' using errcode='40001';end if;insert into erp.daily_plans(organization_id,day) values(p_org,p_day) returning * into h;
 elsif h.version<>p_revision then raise exception 'Újabb napiterv-változat érkezett.' using errcode='40001';end if;
 if p_doc->>'date'<>p_day::text or jsonb_typeof(p_doc->'tasks')<>'array' or jsonb_typeof(p_doc->'workItems')<>'array' or octet_length(p_doc::text)>1000000 then raise exception 'Hibás napi dokumentum.' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_doc->'tasks') x group by x->>'id' having count(*)>1) then raise exception 'Ismétlődő feladat.' using errcode='22023';end if;
 update erp.calendar_slots set active=false where organization_id=p_org and plan_id=h.id;update erp.calendar_reminders set active=false where organization_id=p_org and plan_id=h.id;
 for t in select value from jsonb_array_elements(p_doc->'tasks') loop
 foreach k in array array['workers','vehicles','tools'] loop for ref in select jsonb_array_elements_text(coalesce(t->case k when 'workers' then 'workerIds' when 'vehicles' then 'vehicleIds' else 'toolIds' end,'[]')) loop
 if not exists(select 1 from erp.calendar_catalog where organization_id=p_org and kind=k and id=ref) then raise exception 'Ismeretlen vagy idegen szervezeti törzshivatkozás.' using errcode='22023';end if;end loop;end loop;
 pid:=nullif(t->>'project_id','')::uuid;if pid is not null then select * into proj from erp.garden_projects where organization_id=p_org and id=pid;if not found or proj.work_type is distinct from t->>'work_type' or proj.source_customer_id::text is distinct from t->>'customerId' or proj.source_location_id::text is distinct from t->>'locationId' then raise exception 'Idegen munkához vagy címhez rendelt naptári tétel.' using errcode='42501';end if;end if;
 starts:=null;ends:=null;if nullif(t->>'endTime','') is not null then starts:=(p_day+(t->>'startTime')::time) at time zone 'Europe/Budapest';ends:=(coalesce(nullif(t->>'endDate','')::date,p_day)+(t->>'endTime')::time) at time zone 'Europe/Budapest';if ends<=starts then raise exception 'Hibás befejezési idő.' using errcode='22023';end if;end if;
 count_people:=jsonb_array_length(coalesce(t->'workerIds','[]'));pad:=case when t->>'work_type'='maintenance' then 60 else 0 end;
 linked:=null;visit:=null;
 if starts is not null and pid is not null then
 if (select count(*) from erp.calendar_booking_requests where organization_id=p_org and project_id=pid and state='approved' and start_at<=starts and end_at>=ends and (nullif(t->>'booking_id','') is null or id=(t->>'booking_id')::uuid))>1 then raise exception 'Több jóváhagyott időpont közül válassz konkrét alkalmat.' using errcode='22023';end if;
 select * into visit from erp.calendar_booking_requests where organization_id=p_org and project_id=pid and state='approved' and start_at<=starts and end_at>=ends and (nullif(t->>'booking_id','') is null or id=(t->>'booking_id')::uuid) limit 1;
 if visit.id is not null then
 linked:=visit.id;select array_agg(distinct w) into allworkers from(select jsonb_array_elements_text(t->'workerIds') w union select unnest(workers) from erp.calendar_slots where organization_id=p_org and booking_id=linked and plan_id is not null and active) x;
 select array_agg(distinct w) into allvehicles from(select jsonb_array_elements_text(t->'vehicleIds') w union select unnest(vehicles) from erp.calendar_slots where organization_id=p_org and booking_id=linked and plan_id is not null and active) x;
 reserved:=greatest(visit.headcount,coalesce(cardinality(allworkers),0));perform erp_private.calendar_capacity(p_org,visit.start_at-interval '1 hour',visit.end_at+interval '1 hour',reserved,coalesce(allworkers,'{}'),coalesce(allvehicles,'{}'),null,linked);
 update erp.calendar_slots set headcount=reserved,workers=coalesce(allworkers,'{}'),vehicles=coalesce(allvehicles,'{}') where organization_id=p_org and booking_id=linked and plan_id is null and active;
 elsif nullif(t->>'booking_id','') is not null then raise exception 'A kiválasztott időpont nem ehhez a munkához és időablakhoz tartozik.' using errcode='42501';end if;end if;
 if linked is null and starts is not null and p_source is null and not p_force then perform erp_private.calendar_capacity(p_org,starts-make_interval(mins=>pad),ends+make_interval(mins=>pad),count_people,array(select jsonb_array_elements_text(t->'workerIds')),array(select jsonb_array_elements_text(t->'vehicleIds')),null,null);end if;
 if count_people>0 or starts is not null then insert into erp.calendar_slots(organization_id,plan_id,task_id,booking_id,project_id,day,start_at,end_at,workers,vehicles,headcount,padding,uncertain) values(p_org,h.id,t->>'id',linked,pid,p_day,starts,ends,array(select jsonb_array_elements_text(t->'workerIds')),array(select jsonb_array_elements_text(t->'vehicleIds')),case when linked is null then count_people else 0 end,pad,starts is null) on conflict(organization_id,plan_id,task_id) do update set booking_id=excluded.booking_id,project_id=excluded.project_id,day=excluded.day,start_at=excluded.start_at,end_at=excluded.end_at,workers=excluded.workers,vehicles=excluded.vehicles,headcount=excluded.headcount,padding=excluded.padding,uncertain=excluded.uncertain,active=true;end if;
 end loop;
 insert into erp.daily_plan_versions(organization_id,plan_id,version,document,actor_id,kind) values(p_org,h.id,h.version+1,p_doc,p_person,case when p_source is null then 'save' else 'import' end);
 update erp.daily_plans set version=h.version+1,state='active',updated_at=clock_timestamp(),edited=p_source is null,source_hash=coalesce(p_source,source_hash),source_owner=coalesce(p_source_owner,source_owner),source_conflict=false where id=h.id;
 event:=erp_private.calendar_event(p_org,p_person,case when p_source is null then 'plan_save' else 'plan_import' end,p_day::text,h.version+1,'{}');
 insert into erp.calendar_notifications(organization_id,recipient_id,event_id,kind,target) select p_org,p.id,event,'plan_save',p_day::text from erp.persons p where p.organization_id=p_org and p.active and (exists(select 1 from erp.person_roles r where r.organization_id=p_org and r.person_id=p.id and r.role='office' and r.revoked_at is null and r.valid_from<=now() and (r.valid_until is null or r.valid_until>now())) or exists(select 1 from erp.calendar_catalog c cross join lateral jsonb_array_elements(p_doc->'tasks') assigned_task(value) where c.organization_id=p_org and c.kind='workers' and c.person_id=p.id and (assigned_task.value->'workerIds')?c.id)) on conflict(event_id,recipient_id) do nothing;
 return jsonb_build_object('id',h.id,'day',p_day,'version',h.version+1);
end$$;
create function public.erp_calendar_read(p_org uuid,p_actor uuid,p_session uuid,p_role text,p_filter jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare ctx jsonb;person uuid;from_day date:=coalesce(nullif(p_filter->>'from','')::date,current_date);to_day date:=coalesce(nullif(p_filter->>'to','')::date,from_day);plans jsonb:='[]';catalog jsonb:='[]';rec record;doc jsonb;own_worker_ids jsonb;history jsonb:='[]';begin
 ctx:=erp_private.calendar_scope(p_org,p_actor,p_session,p_role);person:=(ctx->>'person_id')::uuid;
 if p_role='office' and coalesce((p_filter->>'index')::boolean,false) then return jsonb_build_object('years',(select coalesce(jsonb_agg(y order by y),'[]') from(select distinct extract(year from day)::int y from erp.daily_plans where organization_id=p_org) q),'manifest',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'day',day,'version',version,'state',state) order by day),'[]') from erp.daily_plans where organization_id=p_org),'catalog_manifest',(select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'revision',revision) order by kind,id),'[]') from erp.calendar_catalog where organization_id=p_org));end if;
 if to_day<from_day or to_day-from_day>366 then raise exception 'Legfeljebb egyéves időszakot válassz.' using errcode='22023';end if;
 if p_role='client' then return jsonb_build_object('context',ctx-'settings','booking_enabled',coalesce((ctx->'settings'->>'booking')::boolean,false),'bookings',(select coalesce(jsonb_agg(to_jsonb(b)-'organization_id'-'person_id'-'decided_by'),'[]') from erp.calendar_booking_requests b where b.organization_id=p_org and b.person_id=person and b.start_at>=(from_day::timestamp at time zone 'Europe/Budapest') and b.start_at<((to_day+1)::timestamp at time zone 'Europe/Budapest')));end if;
 select coalesce(jsonb_agg(id),'[]') into own_worker_ids from erp.calendar_catalog where organization_id=p_org and kind='workers' and person_id=person;
 for rec in select p.*,v.document from erp.daily_plans p join erp.daily_plan_versions v on v.plan_id=p.id and v.version=p.version where p.organization_id=p_org and p.day between from_day and to_day order by p.day loop
 doc:=rec.document;if p_role<>'office' then if rec.state<>'active' then continue;end if;doc:=jsonb_build_object('id',doc->'id','date',doc->'date','meeting',doc->'meeting','stops',doc->'stops','generalNote','','deletedWorkItemIds','[]'::jsonb,'tasks',(select coalesce(jsonb_agg((t-'notes')||jsonb_build_object('notes','')),'[]') from jsonb_array_elements(doc->'tasks') t where exists(select 1 from jsonb_array_elements_text(t->'workerIds') x where own_worker_ids ? x)),'workItems',(select coalesce(jsonb_agg(w),'[]') from jsonb_array_elements(doc->'workItems') w where not coalesce((w->>'private')::boolean,false) and coalesce(w->'personIds','[]')?person::text));if jsonb_array_length(doc->'tasks')=0 and jsonb_array_length(doc->'workItems')=0 then continue;end if;end if;
 plans:=plans||jsonb_build_array(jsonb_build_object('id',rec.id,'day',rec.day,'version',rec.version,'state',rec.state,'edited',rec.edited,'source_conflict',rec.source_conflict,'document',doc));end loop;
 if p_role='office' then select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'revision',revision,'document',document,'person_id',person_id,'source_kind',source_kind,'edited',edited,'active',active) order by kind,document->>'name',id),'[]') into catalog from erp.calendar_catalog where organization_id=p_org;
 if p_filter->>'history_day' is not null then select coalesce(jsonb_agg(x order by x->>'created_at' desc),'[]') into history from(select jsonb_build_object('version',v.version,'kind',v.kind,'created_at',v.created_at) x from erp.daily_plans p join erp.daily_plan_versions v on v.plan_id=p.id where p.organization_id=p_org and p.day=(p_filter->>'history_day')::date and (nullif(p_filter->>'before_version','') is null or v.version<(p_filter->>'before_version')::bigint) order by v.version desc limit 100) h;end if;
 else select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'document',jsonb_build_object('name',document->'name','color',document->'color'))),'[]') into catalog from erp.calendar_catalog c where c.organization_id=p_org and (c.kind in('workers','vehicles','tools') and exists(select 1 from jsonb_array_elements(plans) p cross join lateral jsonb_array_elements(p->'document'->'tasks') t where (case c.kind when 'workers' then t->'workerIds' when 'vehicles' then t->'vehicleIds' else t->'toolIds' end)?c.id));end if;
 return jsonb_build_object('context',case when p_role='office' then ctx else ctx-'settings' end,'settings_revision',(select revision from erp.calendar_settings where organization_id=p_org),'plans',plans,'catalog',catalog,'history',history,'history_cursor',case when jsonb_array_length(history)=100 then(select min((x->>'version')::bigint) from jsonb_array_elements(history) x) else null end,'import_summary',case when p_role='office' then(select (manifest-'_entries')||jsonb_build_object('can_resume',actor_id=person) from erp_private.calendar_import_runs where organization_id=p_org order by created_at desc,id desc limit 1) else null end,'blocks',case when p_role='office' then(select coalesce(jsonb_agg(to_jsonb(b)),'[]') from erp.calendar_blocks b where organization_id=p_org) else '[]'::jsonb end,'visits',case when p_role='office' then(select coalesce(jsonb_agg(jsonb_build_object('id',id,'project_id',project_id,'start',start_at,'end',end_at)),'[]') from erp.calendar_booking_requests where organization_id=p_org and state='approved') else '[]'::jsonb end,'projects',case when p_role='office' then(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'source_customer_id',source_customer_id,'source_location_id',source_location_id,'work_type',work_type)),'[]') from erp.garden_projects where organization_id=p_org) else '[]'::jsonb end,'people',case when p_role='office' then(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',display_name)),'[]') from erp.persons where organization_id=p_org and active) else '[]'::jsonb end,'bookings',case when p_role='office' then(select coalesce(jsonb_agg(to_jsonb(b)),'[]') from erp.calendar_booking_requests b where organization_id=p_org and state='requested') else '[]'::jsonb end);
end$$;
create function erp_private.calendar_schedule_check(p_org uuid) returns void language plpgsql security definer set search_path='' as $$
 declare slot erp.calendar_slots;point timestamptz;begin
 for slot in select * from erp.calendar_slots where organization_id=p_org and active and not uncertain and (booking_id is null or plan_id is null) loop
 perform erp_private.calendar_capacity(p_org,slot.start_at-make_interval(mins=>slot.padding),slot.end_at+make_interval(mins=>slot.padding),slot.headcount,slot.workers,slot.vehicles,slot.plan_id,slot.booking_id);end loop;
 for point in select distinct start_at-make_interval(mins=>padding) from erp.calendar_slots where organization_id=p_org and active and not uncertain loop perform erp_private.calendar_capacity(p_org,point,point+interval '1 microsecond',0,'{}','{}');end loop;
 end$$;
create function public.erp_calendar_write(p_org uuid,p_actor uuid,p_session uuid,p_role text,p_request uuid,p_fingerprint text,p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare person uuid;cached erp_private.calendar_commands;kind text:=p_command->>'kind';result jsonb;event uuid;revision bigint;item text;catkind text;doc jsonb;plan erp.daily_plans;rec record;worker text;previous_settings jsonb;begin
 person:=erp_private.calendar_office(p_org,p_actor,p_session,p_role);perform pg_advisory_xact_lock(hashtextextended('erp-calendar:'||p_org::text,0));

 if p_request is null or p_fingerprint!~'^[a-f0-9]{64}$' then raise exception 'Hiányzó műveletazonosító.' using errcode='22023';end if;
 select * into cached from erp_private.calendar_commands where organization_id=p_org and request_id=p_request;if found then if cached.actor_id<>person or cached.fingerprint<>p_fingerprint then raise exception 'A kérés más tartalommal már szerepel.' using errcode='40001';end if;return cached.result;end if;
 if kind='batch_plan' then result:='[]'::jsonb;if jsonb_array_length(p_command->'plans')>367 then raise exception 'Túl nagy ismétlődési időszak.' using errcode='22023';end if;for rec in select value from jsonb_array_elements(p_command->'plans') loop result:=result||jsonb_build_array(erp_private.calendar_plan_save(p_org,person,(rec.value->>'day')::date,(rec.value->>'revision')::bigint,rec.value->'document'));end loop;
 elsif kind='save_plan' then result:=erp_private.calendar_plan_save(p_org,person,(p_command->>'day')::date,(p_command->>'revision')::bigint,p_command->'document');
 elsif kind in('withdraw_plan','restore_plan','restore_version') then select * into plan from erp.daily_plans where organization_id=p_org and day=(p_command->>'day')::date for update;if not found or plan.version<>(p_command->>'revision')::bigint then raise exception 'A napiterv megváltozott.' using errcode='40001';end if;
 if kind='restore_version' then select document into doc from erp.daily_plan_versions where organization_id=p_org and plan_id=plan.id and version=(p_command->>'version')::bigint;if doc is null then raise exception 'Nincs ilyen napitervváltozat.' using errcode='22023';end if;result:=erp_private.calendar_plan_save(p_org,person,plan.day,plan.version,doc);
 else if kind='restore_plan' then for rec in select * from erp.calendar_slots where organization_id=p_org and plan_id=plan.id loop if rec.uncertain then if exists(select 1 from erp.calendar_slots where organization_id=p_org and active and booking_id is not null and day between rec.day-1 and rec.day+1) then raise exception 'Ismeretlen végidejű tervet meglévő foglalás mellett előbb pontosíts.' using errcode='22023';end if;elsif rec.booking_id is null then perform erp_private.calendar_capacity(p_org,rec.start_at-make_interval(mins=>rec.padding),rec.end_at+make_interval(mins=>rec.padding),rec.headcount,rec.workers,rec.vehicles,plan.id,null);end if;end loop;end if;update erp.daily_plans set state=case kind when 'withdraw_plan' then 'withdrawn' else 'active' end,edited=true,updated_at=clock_timestamp() where id=plan.id;update erp.calendar_slots set active=kind='restore_plan' where organization_id=p_org and plan_id=plan.id;perform erp_private.calendar_event(p_org,person,kind,plan.day::text,plan.version,'{}');result:=jsonb_build_object('day',plan.day,'state',kind);end if;
 elsif kind='catalog_save' then catkind:=p_command->>'catalog_kind';item:=p_command->'document'->>'id';doc:=p_command->'document';if catkind not in('workers','vehicles','tools','materials','templates','recurrences') or length(item) not between 1 and 120 or jsonb_typeof(doc)<>'object' then raise exception 'Hibás törzsadat.' using errcode='22023';end if;
 select c.revision into revision from erp.calendar_catalog c where organization_id=p_org and c.kind=catkind and c.id=item for update;if coalesce(revision,0)<>(p_command->>'revision')::bigint then raise exception 'A törzsadat megváltozott.' using errcode='40001';end if;
 if nullif(p_command->>'person_id','') is not null and not exists(select 1 from erp.persons where organization_id=p_org and id=(p_command->>'person_id')::uuid and active) then raise exception 'Idegen személy.' using errcode='42501';end if;
 insert into erp.calendar_catalog(organization_id,kind,id,document,person_id,revision,active) values(p_org,catkind,item,doc,nullif(p_command->>'person_id','')::uuid,coalesce(revision,0)+1,coalesce((doc->>'active')::boolean,true)) on conflict on constraint calendar_catalog_pkey do update set document=excluded.document,person_id=excluded.person_id,revision=excluded.revision,active=excluded.active,edited=true;
 event:=erp_private.calendar_event(p_org,person,kind,catkind||':'||item,coalesce(revision,0)+1,jsonb_build_object('document',doc));result:=jsonb_build_object('id',item,'revision',coalesce(revision,0)+1);
 elsif kind='settings' then select document into previous_settings from erp.calendar_settings where organization_id=p_org;insert into erp.calendar_settings(organization_id) values(p_org) on conflict do nothing;select s.revision into revision from erp.calendar_settings s where organization_id=p_org for update;if revision<>(p_command->>'revision')::bigint then raise exception 'A beállítás megváltozott.' using errcode='40001';end if;doc:=p_command->'document';if jsonb_typeof(doc->'roles')<>'object' or jsonb_typeof(doc->'windows')<>'array' or coalesce((doc->>'capacity')::integer,-1) not between 0 and 1000 then raise exception 'Hibás naptári beállítás.' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(doc->'roles') f where f.key not in('client','construction_lead','maintenance_lead','construction_worker','gardener') or jsonb_typeof(f.value)<>'boolean') then raise exception 'Hibás szerepkörkapcsoló.' using errcode='22023';end if;
 for rec in select value from jsonb_array_elements(doc->'windows') loop if (rec.value->>'weekday')::integer not between 0 and 6 or (rec.value->>'end')::time<=(rec.value->>'start')::time then raise exception 'Hibás munkaidőablak.' using errcode='22023';end if;end loop;
 update erp.calendar_settings set document=doc,revision=erp.calendar_settings.revision+1,updated_by=person,updated_at=clock_timestamp() where organization_id=p_org;
 if previous_settings->'capacity' is distinct from doc->'capacity' or previous_settings->'windows' is distinct from doc->'windows' then perform erp_private.calendar_schedule_check(p_org);end if;
 perform erp_private.calendar_event(p_org,person,kind,'settings',revision+1,doc);result:=jsonb_build_object('revision',revision+1);
 elsif kind='block_save' then doc:=p_command->'document';item:=p_command->>'id';select b.revision into revision from erp.calendar_blocks b where organization_id=p_org and id=item::uuid for update;if coalesce(revision,0)<>(p_command->>'revision')::bigint then raise exception 'A tiltás megváltozott.' using errcode='40001';end if;
 if (doc->>'end_date')::date<(doc->>'start_date')::date or (doc->>'end_time')::time=(doc->>'start_time')::time or coalesce(doc->>'repeat','once') not in('once','weekly') then raise exception 'Hibás időtiltás.' using errcode='22023';end if;
 for worker in select jsonb_array_elements_text(coalesce(doc->'workers','[]')) loop if not exists(select 1 from erp.calendar_catalog where organization_id=p_org and erp.calendar_catalog.kind='workers' and id=worker) then raise exception 'Idegen munkatársi tiltás.' using errcode='42501';end if;end loop;
 insert into erp.calendar_blocks(id,organization_id,document,active,revision,actor_id) values(item::uuid,p_org,doc,coalesce((p_command->>'active')::boolean,true),coalesce(revision,0)+1,person) on conflict(id) do update set document=excluded.document,active=excluded.active,revision=excluded.revision,actor_id=excluded.actor_id where erp.calendar_blocks.organization_id=p_org;if not found then raise exception 'Idegen blokk.' using errcode='42501';end if;
 perform erp_private.calendar_schedule_check(p_org);
 perform erp_private.calendar_event(p_org,person,kind,item,coalesce(revision,0)+1,doc);result:=jsonb_build_object('id',item,'revision',coalesce(revision,0)+1);
 elsif kind='sent' then if p_command->>'confirmed'<>'true' then raise exception 'Az elküldést külön erősítsd meg.' using errcode='22023';end if;perform erp_private.calendar_event(p_org,person,'manual_sent',p_command->>'day',null,jsonb_build_object('recipients',p_command->'recipients'));result:='{"sent":true}';
 else raise exception 'Ismeretlen naptári művelet.' using errcode='22023';end if;
 insert into erp_private.calendar_commands values(p_org,p_request,person,kind,p_fingerprint,result,clock_timestamp());return result;
end$$;
create function public.erp_calendar_import(p_org uuid,p_actor uuid,p_session uuid,p_role text,p_request uuid,p_owner uuid,p_fingerprint text,p_manifest jsonb,p_rows jsonb,p_apply boolean default false,p_resolutions jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare person uuid;run erp_private.calendar_import_runs;row jsonb;key text;hash text;cat_kind text;item jsonb;existing erp.calendar_catalog;h erp.daily_plans;applied integer:=0;unchanged integer:=0;conflicts jsonb:='[]';found_row boolean;result jsonb;begin
 person:=erp_private.calendar_office(p_org,p_actor,p_session,p_role);perform pg_advisory_xact_lock(hashtextextended('erp-calendar:'||p_org::text,0));
 if p_rows is null then
 select * into run from erp_private.calendar_import_runs where organization_id=p_org and id=p_request for update;
 if run.id is null or run.actor_id<>person or run.source_hash is distinct from p_fingerprint then raise exception 'Az importelőnézet nem elérhető.' using errcode='42501';end if;
 select coalesce(jsonb_agg(r.payload order by case when r.payload->>'kind'='archive' then 0 when r.payload->>'kind'='catalog' then 1 else 2 end,r.source_key),'[]') into p_rows from erp_private.calendar_source_rows r join jsonb_array_elements(run.manifest->'_entries') e on e->>'key'=r.source_key and e->>'hash'=r.source_hash where r.organization_id=p_org;
 if jsonb_array_length(p_rows)<>jsonb_array_length(run.manifest->'_entries') then raise exception 'Hiányos saját importarchívum.' using errcode='22023';end if;
 p_manifest:=run.manifest;p_owner:=run.source_owner;end if;
 if p_request is null or p_fingerprint!~'^[a-f0-9]{64}$' or jsonb_typeof(p_rows)<>'array' then raise exception 'Hibás forráscsomag.' using errcode='22023';end if;
 select * into run from erp_private.calendar_import_runs where organization_id=p_org and id=p_request for update;if found then if run.source_hash<>p_fingerprint or run.actor_id<>person then raise exception 'Más tartalmú importazonosító.' using errcode='40001';end if;if run.state='applied' then return run.manifest||jsonb_build_object('state','applied','replayed',true);end if;else insert into erp_private.calendar_import_runs(id,organization_id,actor_id,source_owner,manifest,source_hash,state) values(p_request,p_org,person,p_owner,p_manifest,p_fingerprint,'preview');end if;
 for row in select value from jsonb_array_elements(p_rows) loop key:=row->>'key';hash:=row->>'hash';if key is null or hash!~'^[a-f0-9]{64}$' then raise exception 'Hiányzó forráslenyomat.' using errcode='22023';end if;
 insert into erp_private.calendar_source_rows(organization_id,run_id,source_key,source_hash,payload,updated_at,deleted) values(p_org,p_request,key,hash,row,nullif(row->>'updated_at','')::timestamptz,coalesce((row->>'deleted')::boolean,false)) on conflict do nothing;
 if row->>'kind'='catalog' then cat_kind:=row->>'catalog_kind';item:=row->'document';if cat_kind not in('workers','vehicles','tools','materials','templates','recurrences') then raise exception 'Hibás importált törzs.' using errcode='22023';end if;
 select * into existing from erp.calendar_catalog where organization_id=p_org and erp.calendar_catalog.kind=cat_kind and id=item->>'id' for update;
 if found and existing.source_hash=hash then unchanged:=unchanged+1;continue;end if;
 if existing.id is not null and existing.edited and coalesce(p_resolutions->>key,'') not in('source','erp') then conflicts:=conflicts||jsonb_build_array(jsonb_build_object('key',key,'name',item->>'name','kind','catalog'));continue;end if;
 if p_apply and p_resolutions->>key='erp' then update erp.calendar_catalog set source_hash=hash where organization_id=p_org and erp.calendar_catalog.kind=cat_kind and id=item->>'id';end if;
 if p_apply and coalesce(p_resolutions->>key,'')<>'erp' then insert into erp.calendar_catalog(organization_id,kind,id,document,revision,source_kind,source_hash,edited,active) values(p_org,cat_kind,item->>'id',item,coalesce(existing.revision,0)+1,'napi',hash,p_manifest->>'source'='file',coalesce((item->>'active')::boolean,true)) on conflict on constraint calendar_catalog_pkey do update set document=excluded.document,revision=excluded.revision,source_hash=excluded.source_hash,edited=excluded.edited,active=excluded.active;applied:=applied+1;end if;
 elsif row->>'kind'='plan' then select * into h from erp.daily_plans where organization_id=p_org and day=(row->>'day')::date for update;
 if found and h.source_hash=hash then unchanged:=unchanged+1;continue;end if;
 if h.id is not null and h.edited and coalesce(p_resolutions->>key,'') not in('source','erp') then conflicts:=conflicts||jsonb_build_array(jsonb_build_object('key',key,'day',row->>'day','kind','plan'));if p_apply then update erp.daily_plans set source_conflict=true where id=h.id;end if;continue;end if;
 if p_apply and p_resolutions->>key='erp' then update erp.daily_plans set source_hash=hash,source_conflict=false where id=h.id;end if;
 if p_apply and coalesce(p_resolutions->>key,'')<>'erp' then if coalesce((row->>'deleted')::boolean,false) then if h.id is not null then update erp.daily_plans set state='withdrawn',edited=false,source_hash=hash,updated_at=clock_timestamp() where id=h.id;update erp.calendar_slots set active=false where organization_id=p_org and plan_id=h.id;end if;else perform erp_private.calendar_plan_save(p_org,person,(row->>'day')::date,coalesce(h.version,0),row->'document',hash,p_owner);if p_manifest->>'source'='file' then update erp.daily_plans set edited=true where organization_id=p_org and day=(row->>'day')::date;end if;end if;applied:=applied+1;end if;
 elsif row->>'kind'<>'archive' then raise exception 'Ismeretlen importált rekord.' using errcode='22023';end if;
 existing:=null;h:=null;end loop;
 result:=p_manifest||jsonb_build_object('applied',applied,'unchanged',unchanged,'conflicts',conflicts,'state',case when not p_apply then 'preview' when jsonb_array_length(conflicts)>0 then 'conflict' else 'applied' end,'run_id',p_request,'fingerprint',p_fingerprint);
 update erp_private.calendar_import_runs set state=result->>'state',manifest=result where id=p_request and organization_id=p_org;
 if p_apply then perform erp_private.calendar_event(p_org,person,'import',p_request::text,null,result);end if;return result;
end$$;
create function public.erp_calendar_booking(p_org uuid,p_actor uuid,p_session uuid,p_role text,p_request uuid,p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare ctx jsonb;person uuid;kind text:=p_command->>'kind';b erp.calendar_booking_requests;site erp.work_sites;ca erp_private.client_accounts;command jsonb;preview jsonb;result jsonb;slots jsonb:='[]';d date;w jsonb;at_time timestamptz;finish timestamptz;duration integer;people integer;event uuid;cached erp_private.calendar_commands;fingerprint text:=coalesce(p_command->>'_fingerprint',repeat(md5(p_command::text),2));begin
 ctx:=erp_private.calendar_scope(p_org,p_actor,p_session,p_role);person:=(ctx->>'person_id')::uuid;if p_role not in('office','client') then raise exception 'Időpontot iroda vagy saját ügyfél kérhet.' using errcode='42501';end if;
 if p_role='client' and not coalesce((ctx->'settings'->>'booking')::boolean,false) then raise exception 'Az online időpontkérés nincs bekapcsolva.' using errcode='42501';end if;
 if kind<>'availability' then perform pg_advisory_xact_lock(hashtextextended('maintenance-catalog:'||p_org::text,0));perform pg_advisory_xact_lock(hashtextextended('erp-calendar:'||p_org::text,0));end if;
 if kind not in('availability','request') then select * into cached from erp_private.calendar_commands where organization_id=p_org and request_id=p_request;if found then if cached.actor_id<>person or cached.fingerprint<>fingerprint or cached.kind<>'booking' then raise exception 'Eltérő ismételt foglalási döntés.' using errcode='40001';end if;return cached.result;end if;end if;
 if kind in('availability','request') then
 select * into site from erp.work_sites where organization_id=p_org and source_location_id=(p_command->>'location_id')::uuid and source_active and source_approved;
 if not found then raise exception 'Aktív munkavégzési címet válassz.' using errcode='22023';end if;
 if p_role='client' then ca:=erp_private.require_client_session(p_actor,p_session);if not exists(select 1 from erp.client_site_access where organization_id=p_org and account_id=ca.id and active and source_customer_id=site.source_customer_id and source_location_id=site.source_location_id) then raise exception 'Nem saját munkavégzési cím.' using errcode='42501';end if;end if;
 people:=(p_command->>'headcount')::integer;if people not between 1 and 1000 then raise exception 'Hibás létszám.' using errcode='22023';end if;
 if kind='availability' then duration:=(p_command->>'minutes')::integer;if duration not between 15 and 720 or (p_command->>'to')::date-(p_command->>'from')::date not between 0 and 31 then raise exception 'Legfeljebb 31 napot és 15–720 percet válassz.' using errcode='22023';end if;
 for d in select generate_series((p_command->>'from')::date,(p_command->>'to')::date,interval '1 day')::date loop for w in select value from jsonb_array_elements(coalesce(ctx->'settings'->'windows','[]')) where (value->>'weekday')::integer=extract(dow from d)::integer loop
 at_time:=((d+(w->>'start')::time) at time zone 'Europe/Budapest')+interval '1 hour';finish:=((d+(w->>'end')::time) at time zone 'Europe/Budapest')-interval '1 hour';
 while at_time+make_interval(mins=>duration)<=finish loop begin perform erp_private.calendar_capacity(p_org,at_time-interval '1 hour',at_time+make_interval(mins=>duration)+interval '1 hour',people,'{}','{}');if at_time>clock_timestamp() then slots:=slots||jsonb_build_array(jsonb_build_object('start',at_time,'end',at_time+make_interval(mins=>duration),'headcount',people));end if;exception when sqlstate '22023' then null;end;at_time:=at_time+interval '30 minutes';end loop;end loop;end loop;return jsonb_build_object('slots',slots);end if;
 if p_request is null or p_command->>'confirmed'<>'true' then raise exception 'Az időpontkérést erősítsd meg.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('erp-calendar:'||p_org::text,0));select * into b from erp.calendar_booking_requests where organization_id=p_org and id=p_request;if found then if b.person_id<>person or b.location_id<>site.source_location_id or b.start_at<>(p_command->>'start')::timestamptz or b.end_at<>(p_command->>'end')::timestamptz or b.headcount<>people or b.note<>coalesce(p_command->>'note','') then raise exception 'Eltérő ismételt időpontkérés.' using errcode='40001';end if;return jsonb_build_object('id',b.id,'state',b.state,'replayed',true);end if;
 perform erp_private.calendar_capacity(p_org,(p_command->>'start')::timestamptz-interval '1 hour',(p_command->>'end')::timestamptz+interval '1 hour',people,'{}','{}');
 command:=jsonb_build_object('kind','request','request_type','maintenance','location_id',site.source_location_id,'description',coalesce(nullif(p_command->>'note',''),'Karbantartási időpontkérés'),'day',((p_command->>'start')::timestamptz at time zone 'Europe/Budapest')::date,'people',people,'hours',extract(epoch from ((p_command->>'end')::timestamptz-(p_command->>'start')::timestamptz))/3600);
 perform set_config('erp.calendar_booking_request',p_request::text,true);preview:=public.erp_maintenance_preview(p_org,p_actor,p_session,null,p_role,command,'{}');result:=public.erp_maintenance_write(p_org,p_actor,p_session,null,p_role,p_request,repeat(md5(command::text),2),command,'{}',preview->>'token',true);
 insert into erp.calendar_booking_requests(id,organization_id,person_id,customer_id,location_id,project_id,maintenance_request_id,start_at,end_at,headcount,note) select p_request,p_org,person,site.source_customer_id,site.source_location_id,r.project_id,r.id,(p_command->>'start')::timestamptz,(p_command->>'end')::timestamptz,people,coalesce(p_command->>'note','') from erp.maintenance_requests r where r.organization_id=p_org and r.id=p_request;
 event:=erp_private.calendar_event(p_org,person,'booking_request',p_request::text,1,'{}');insert into erp.calendar_notifications(organization_id,recipient_id,event_id,kind,target) select p_org,r.person_id,event,'booking_request',p_request::text from erp.person_roles r where r.organization_id=p_org and r.role='office' and r.revoked_at is null and r.valid_from<=now() and (r.valid_until is null or r.valid_until>now()) on conflict do nothing;return jsonb_build_object('id',p_request,'state','requested');
 end if;
 select * into b from erp.calendar_booking_requests where organization_id=p_org and id=(p_command->>'booking_id')::uuid for update;
 if not found or b.revision<>(p_command->>'revision')::bigint then raise exception 'Az időpontkérés megváltozott.' using errcode='40001';end if;
 if kind not in('approve','reject','withdraw') or p_role<>'office' and (kind<>'withdraw' or b.person_id<>person) then raise exception 'Ehhez a döntéshez nincs jogosultság.' using errcode='42501';end if;
 if kind='withdraw' and b.state='approved' then
 if p_role<>'office' then raise exception 'Jóváhagyott időpontot az iroda módosíthat.' using errcode='42501';end if;
 if exists(select 1 from erp.calendar_slots where organization_id=p_org and booking_id=b.id and plan_id is not null and active) then raise exception 'Az időpont napitervben szerepel; az iroda előbb módosítsa a napi beosztást.' using errcode='22023';end if;
 if length(btrim(coalesce(p_command->>'reason','')))=0 then raise exception 'A visszavonás indokát írd le.' using errcode='22023';end if;
 update erp.calendar_booking_requests set state='withdrawn',revision=revision+1,decided_by=person where id=b.id;update erp.calendar_slots set active=false where organization_id=p_org and booking_id=b.id;
 event:=erp_private.calendar_event(p_org,person,'booking_withdrawn',b.id::text,b.revision+1,jsonb_build_object('reason',p_command->>'reason'));insert into erp.calendar_notifications(organization_id,recipient_id,event_id,kind,target) values(p_org,b.person_id,event,'booking_withdrawn',b.id::text);
 result:=jsonb_build_object('id',b.id,'state','withdrawn');insert into erp_private.calendar_commands(organization_id,request_id,actor_id,kind,fingerprint,result) values(p_org,p_request,person,'booking',fingerprint,result);return result;
 end if;
 command:=jsonb_build_object('kind',case kind when 'withdraw' then 'withdraw_request' else kind end,'day',(b.start_at at time zone 'Europe/Budapest')::date,'revision',(select revision from erp.maintenance_requests where organization_id=p_org and id=b.maintenance_request_id),'reason',coalesce(p_command->>'reason',''));
 preview:=public.erp_maintenance_preview(p_org,p_actor,p_session,b.project_id,p_role,command,'{}');result:=public.erp_maintenance_write(p_org,p_actor,p_session,b.project_id,p_role,p_request,repeat(md5(command::text),2),command,'{}',preview->>'token',true);
 result:=jsonb_build_object('id',b.id,'result',result,'state',case kind when 'approve' then 'approved' when 'reject' then 'rejected' else 'withdrawn' end);insert into erp_private.calendar_commands(organization_id,request_id,actor_id,kind,fingerprint,result) values(p_org,p_request,person,'booking',fingerprint,result);return result;
end$$;
create function erp_private.calendar_maintenance_change() returns trigger language plpgsql security definer set search_path='' as $$
declare b erp.calendar_booking_requests;person uuid;event uuid;w_ids text[];v_ids text[];reserved integer;begin
 if old.state is not distinct from new.state then return new;end if;
 for b in select * from erp.calendar_booking_requests where organization_id=new.organization_id and maintenance_request_id=new.id for update loop
 if new.state='approved' then
 update erp.calendar_slots set booking_id=b.id,headcount=0 where organization_id=b.organization_id and project_id=b.project_id and plan_id is not null and active and not uncertain and start_at>=b.start_at and end_at<=b.end_at;
 select array_agg(distinct w) into w_ids from erp.calendar_slots s cross join lateral unnest(s.workers) w where s.organization_id=b.organization_id and s.booking_id=b.id and s.plan_id is not null and s.active;
 select array_agg(distinct w) into v_ids from erp.calendar_slots s cross join lateral unnest(s.vehicles) w where s.organization_id=b.organization_id and s.booking_id=b.id and s.plan_id is not null and s.active;reserved:=greatest(b.headcount,coalesce(cardinality(w_ids),0));
 perform erp_private.calendar_capacity(b.organization_id,b.start_at-interval '1 hour',b.end_at+interval '1 hour',reserved,coalesce(w_ids,'{}'),coalesce(v_ids,'{}'),null,b.id);
 insert into erp.calendar_slots(organization_id,booking_id,project_id,day,start_at,end_at,headcount,padding,workers,vehicles) values(b.organization_id,b.id,b.project_id,(b.start_at at time zone 'Europe/Budapest')::date,b.start_at,b.end_at,reserved,60,coalesce(w_ids,'{}'),coalesce(v_ids,'{}'));
 else update erp.calendar_slots set active=false where organization_id=b.organization_id and booking_id=b.id;end if;
 update erp.calendar_booking_requests set state=case new.state when 'approved' then 'approved' when 'rejected' then 'rejected' when 'withdrawn' then 'withdrawn' else 'requested' end,revision=revision+1,decided_by=new.decision_by where id=b.id;
 person:=coalesce(new.decision_by,new.author_id);event:=erp_private.calendar_event(b.organization_id,person,'booking_'||new.state,b.id::text,b.revision+1,'{}');insert into erp.calendar_notifications(organization_id,recipient_id,event_id,kind,target) values(b.organization_id,b.person_id,event,'booking_'||new.state,b.id::text);end loop;return new;
end$$;
create trigger erp_calendar_maintenance_change after update of state on erp.maintenance_requests for each row execute function erp_private.calendar_maintenance_change();
create function erp_private.calendar_reconcile_bookings(p_org uuid) returns void language plpgsql security definer set search_path='' as $$
 declare b erp.calendar_booking_requests;w_ids text[];v_ids text[];begin
 for b in select * from erp.calendar_booking_requests where organization_id=p_org and state='approved' loop
 select array_agg(distinct w) into w_ids from erp.calendar_slots s cross join lateral unnest(s.workers) w where s.organization_id=p_org and s.booking_id=b.id and s.plan_id is not null and s.active;
 select array_agg(distinct w) into v_ids from erp.calendar_slots s cross join lateral unnest(s.vehicles) w where s.organization_id=p_org and s.booking_id=b.id and s.plan_id is not null and s.active;
 update erp.calendar_slots set headcount=greatest(b.headcount,coalesce(cardinality(w_ids),0)),workers=coalesce(w_ids,'{}'),vehicles=coalesce(v_ids,'{}') where organization_id=p_org and booking_id=b.id and plan_id is null and active;end loop;end$$;
create function erp_private.calendar_plan_change() returns trigger language plpgsql security definer set search_path='' as $$
declare doc jsonb;w jsonb;person uuid;event uuid;meeting timestamptz;time_text text;due timestamptz;begin
 perform erp_private.calendar_reconcile_bookings(new.organization_id);update erp.calendar_reminders set active=false where organization_id=new.organization_id and plan_id=new.id;if new.state<>'active' then return new;end if;
 select document into doc from erp.daily_plan_versions where plan_id=new.id and version=new.version;
 for w in select value from jsonb_array_elements(coalesce(doc->'workItems','[]')) where nullif(value->>'appointmentTime','') is not null loop
 meeting:=(new.day+(w->>'appointmentTime')::time) at time zone 'Europe/Budapest';
 for person in select r.person_id from erp.person_roles r where r.organization_id=new.organization_id and r.role='office' and r.revoked_at is null and r.valid_from<=now() and (r.valid_until is null or r.valid_until>now()) union select p.id from erp.persons p where p.organization_id=new.organization_id and p.active and coalesce(w->'personIds','[]')?p.id::text loop
 for due in select meeting-interval '1 hour' union select (new.day+x::time) at time zone 'Europe/Budapest' from jsonb_array_elements_text(coalesce(w->'reminderTimes','[]')) x loop
 if due<meeting then insert into erp.calendar_reminders(organization_id,plan_id,version,item_id,person_id,due_at,event_at) values(new.organization_id,new.id,new.version,w->>'id',person,due,meeting) on conflict(plan_id,version,item_id,person_id,due_at) do update set active=true;end if;end loop;end loop;end loop;
 return new;
end$$;
create trigger erp_calendar_plan_change after update of version,state on erp.daily_plans for each row execute function erp_private.calendar_plan_change();
create function public.erp_calendar_notifications(p_org uuid,p_actor uuid,p_session uuid,p_role text,p_read uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;begin
 ctx:=erp_private.calendar_scope(p_org,p_actor,p_session,p_role);if p_read is not null then update erp.calendar_notifications set read_at=coalesce(read_at,clock_timestamp()) where organization_id=p_org and recipient_id=(ctx->>'person_id')::uuid and id=p_read;end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('id',id,'kind',kind,'target',target,'read_at',read_at,'created_at',created_at) order by created_at desc),'[]') from erp.calendar_notifications where organization_id=p_org and recipient_id=(ctx->>'person_id')::uuid and (read_at is null or created_at>now()-interval '30 days'));
end$$;
create function public.erp_calendar_push(p_org uuid,p_actor uuid,p_session uuid,p_role text,p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;person uuid;subscription jsonb;begin
 ctx:=erp_private.calendar_scope(p_org,p_actor,p_session,p_role);person:=(ctx->>'person_id')::uuid;if p_role='client' then raise exception 'Ehhez a naptári emlékeztetőhöz nincs jogosultság.' using errcode='42501';end if;
 if p_command->>'kind'='read' then return jsonb_build_object('public_key',(select decrypted_secret from vault.decrypted_secrets where name='erp_calendar_vapid_public_key'),'subscriptions',(select count(*) from erp.calendar_push_subscriptions where organization_id=p_org and person_id=person and enabled));end if;
 subscription:=p_command->'subscription';if subscription->>'endpoint' !~ '^https://(fcm[.]googleapis[.]com|updates[.]push[.]services[.]mozilla[.]com|web[.]push[.]apple[.]com|[a-zA-Z0-9.-]+[.]notify[.]windows[.]com)/' or length(subscription->>'endpoint')>4096 or length(coalesce(subscription->'keys'->>'p256dh','')) not between 30 and 300 or length(coalesce(subscription->'keys'->>'auth','')) not between 10 and 200 then raise exception 'Hibás eszközfeliratkozás.' using errcode='22023';end if;
 if exists(select 1 from erp.calendar_push_subscriptions where endpoint=subscription->>'endpoint' and (organization_id<>p_org or person_id<>person)) then raise exception 'Az eszköz másik saját fiókhoz tartozik; előbb kapcsold ki ott.' using errcode='42501';end if;
 insert into erp.calendar_push_subscriptions(organization_id,person_id,endpoint,document,enabled) values(p_org,person,subscription->>'endpoint',subscription,p_command->>'kind'='enable') on conflict(endpoint) do update set document=excluded.document,enabled=excluded.enabled,updated_at=clock_timestamp();return jsonb_build_object('enabled',p_command->>'kind'='enable');
end$$;
create function erp_private.calendar_push_allowed(p_org uuid,p_person uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from erp.user_accounts a join erp.persons p on p.organization_id=a.organization_id and p.id=a.person_id where a.organization_id=p_org and a.person_id=p_person and a.active and p.active) and (exists(select 1 from erp.person_roles r left join erp.calendar_settings st on st.organization_id=r.organization_id where r.organization_id=p_org and r.person_id=p_person and r.role='office' and r.revoked_at is null and r.valid_from<=now() and (r.valid_until is null or r.valid_until>now()) and coalesce((st.document->>'office')::boolean,true)) or exists(select 1 from erp.calendar_settings st cross join lateral jsonb_each_text(st.document->'roles') flag join erp_private.staff_accounts a on a.organization_id=st.organization_id and a.person_id=p_person where st.organization_id=p_org and flag.key<>'client' and flag.value='true' and a.active and not a.setup_pending and (flag.key in('construction_worker','gardener') or exists(select 1 from erp.project_assignments pa where pa.organization_id=p_org and pa.person_id=p_person and pa.role=flag.key and pa.revoked_at is null and pa.valid_from<=now() and (pa.valid_until is null or pa.valid_until>now())))))
$$;
create function public.erp_calendar_deliveries(p_token text,p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare secret text;row record;claimed jsonb:='[]';ok boolean;begin
 select decrypted_secret into secret from vault.decrypted_secrets where name='erp_calendar_job_token';if secret is null or p_token is distinct from secret then raise exception 'Érvénytelen saját ERP-ütemező.' using errcode='42501';end if;
 if p_command->>'kind'='lease' then
 insert into erp_private.calendar_reminder_deliveries(organization_id,reminder_id,subscription_id) select r.organization_id,r.id,s.id from erp.calendar_reminders r join erp.daily_plans p on p.organization_id=r.organization_id and p.id=r.plan_id and p.version=r.version and p.state='active' join erp.calendar_push_subscriptions s on s.organization_id=r.organization_id and s.person_id=r.person_id and s.enabled where r.active and r.event_at>clock_timestamp() and r.due_at<=clock_timestamp() and r.due_at>clock_timestamp()-interval '30 minutes' on conflict do nothing;
 for row in select d.id,d.attempts,r.organization_id,r.plan_id,r.version,r.person_id,r.item_id,s.document,s.id subscription_id from erp_private.calendar_reminder_deliveries d join erp.calendar_reminders r on r.id=d.reminder_id and r.organization_id=d.organization_id join erp.calendar_push_subscriptions s on s.id=d.subscription_id and s.organization_id=d.organization_id join erp.daily_plans p on p.id=r.plan_id and p.organization_id=r.organization_id where d.state in('pending','failed','sending') and d.attempts<5 and d.next_at<=clock_timestamp() and (d.lease_until is null or d.lease_until<clock_timestamp()) and r.active and r.event_at>clock_timestamp() and r.due_at>clock_timestamp()-interval '30 minutes' and p.version=r.version and p.state='active' and s.enabled order by d.next_at,d.id limit 60 for update of d skip locked loop
 ok:=erp_private.calendar_push_allowed(row.organization_id,row.person_id);
 if not ok then update erp_private.calendar_reminder_deliveries set state='expired',updated_at=clock_timestamp() where id=row.id;continue;end if;
 update erp_private.calendar_reminder_deliveries set state='sending',attempts=attempts+1,lease_until=clock_timestamp()+interval '2 minutes',updated_at=clock_timestamp() where id=row.id;
 claimed:=claimed||jsonb_build_array(jsonb_build_object('id',row.id,'attempt',row.attempts+1,'subscription',row.document,'tag','erp-calendar-'||row.id::text));end loop;
 return jsonb_build_object('deliveries',claimed,'public_key',(select decrypted_secret from vault.decrypted_secrets where name='erp_calendar_vapid_public_key'),'private_key',(select decrypted_secret from vault.decrypted_secrets where name='erp_calendar_vapid_private_key'));
 elsif p_command->>'kind'='authorize' then
 return jsonb_build_object('authorized',exists(select 1 from erp_private.calendar_reminder_deliveries d join erp.calendar_reminders r on r.id=d.reminder_id and r.organization_id=d.organization_id join erp.calendar_push_subscriptions s on s.id=d.subscription_id and s.organization_id=d.organization_id join erp.daily_plans p on p.id=r.plan_id and p.organization_id=r.organization_id where d.id=(p_command->>'id')::uuid and d.state='sending' and d.attempts=(p_command->>'attempt')::integer and d.lease_until>clock_timestamp() and r.active and r.event_at>clock_timestamp() and r.version=p.version and p.state='active' and s.enabled and erp_private.calendar_push_allowed(r.organization_id,r.person_id)));
 elsif p_command->>'kind'='complete' then
 update erp_private.calendar_reminder_deliveries set state=case p_command->>'result' when 'sent' then 'sent' when 'expired' then 'expired' when 'cancelled' then 'expired' else 'failed' end,next_at=clock_timestamp()+make_interval(mins=>least(15,attempts*2)),lease_until=null,updated_at=clock_timestamp() where id=(p_command->>'id')::uuid and state='sending' and attempts=(p_command->>'attempt')::integer;
 ok:=found;if ok and p_command->>'result'='expired' then update erp.calendar_push_subscriptions set enabled=false where id=(select subscription_id from erp_private.calendar_reminder_deliveries where id=(p_command->>'id')::uuid);end if;
 return jsonb_build_object('saved',ok);
 elsif p_command->>'kind'='cleanup' then delete from erp_private.calendar_reminder_deliveries d where d.updated_at<clock_timestamp()-interval '30 days' and (d.state in('sent','expired') or d.attempts>=5 or not exists(select 1 from erp.calendar_reminders r where r.id=d.reminder_id and r.active and r.event_at>clock_timestamp()));return '{"done":true}';
 else raise exception 'Ismeretlen kézbesítési művelet.' using errcode='22023';end if;
end$$;
create function public.erp_calendar_options(p_org uuid,p_actor uuid,p_session uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare person uuid;settings jsonb;office boolean;roles jsonb:='[]';r text;c erp_private.client_accounts;s erp_private.staff_accounts;begin
 select a.person_id into person from erp.user_accounts a join erp.persons p on p.organization_id=a.organization_id and p.id=a.person_id where a.organization_id=p_org and a.auth_user_id=p_actor and a.active and p.active;if person is null then raise exception 'Nincs saját ERP-hozzáférés.' using errcode='42501';end if;
 office:=exists(select 1 from erp.person_roles where organization_id=p_org and person_id=person and role='office' and revoked_at is null and valid_from<=now() and (valid_until is null or valid_until>now()));
 select document into settings from erp.calendar_settings where organization_id=p_org;settings:=coalesce(settings,'{"office":true,"roles":{},"booking":false}');
 if office then roles:='["office"]';else
 if exists(select 1 from erp_private.client_accounts where organization_id=p_org and person_id=person and active) then c:=erp_private.require_client_session(p_actor,p_session);if coalesce((settings->'roles'->>'client')::boolean,false) then roles:=roles||'"client"'::jsonb;end if;end if;
 if exists(select 1 from erp_private.staff_accounts where organization_id=p_org and person_id=person and active) then s:=erp_private.require_staff_session(p_actor,p_session);foreach r in array array['construction_lead','maintenance_lead','construction_worker','gardener'] loop if coalesce((settings->'roles'->>r)::boolean,false) and (r in('construction_worker','gardener') or exists(select 1 from erp.project_assignments where organization_id=p_org and person_id=person and role=r and revoked_at is null and valid_from<=now() and (valid_until is null or valid_until>now()))) then roles:=roles||to_jsonb(r);end if;end loop;end if;end if;
 return jsonb_build_object('unread',case when jsonb_array_length(roles)>0 then(select count(*) from erp.calendar_notifications where organization_id=p_org and recipient_id=person and read_at is null) else 0 end,'roles',roles,'booking',coalesce((settings->>'booking')::boolean,false));end$$;

create function erp_private.calendar_enqueue_reminders() returns bigint language plpgsql security definer set search_path='' as $$
 declare token text;request_id bigint;begin
 delete from erp_private.calendar_reminder_deliveries d where d.updated_at<clock_timestamp()-interval '30 days' and (d.state in('sent','expired') or d.attempts>=5 or not exists(select 1 from erp.calendar_reminders r where r.id=d.reminder_id and r.active and r.event_at>clock_timestamp()));
 if not exists(select 1 from erp.calendar_reminders r join erp.daily_plans p on p.organization_id=r.organization_id and p.id=r.plan_id and p.version=r.version and p.state='active' join erp.calendar_push_subscriptions sub on sub.organization_id=r.organization_id and sub.person_id=r.person_id and sub.enabled left join erp_private.calendar_reminder_deliveries d on d.reminder_id=r.id and d.subscription_id=sub.id where r.active and r.due_at<=clock_timestamp() and r.due_at>clock_timestamp()-interval '30 minutes' and r.event_at>clock_timestamp() and erp_private.calendar_push_allowed(r.organization_id,r.person_id) and (d.id is null or d.state in('pending','failed','sending') and d.attempts<5 and d.next_at<=clock_timestamp() and (d.lease_until is null or d.lease_until<clock_timestamp()))) then return null;end if;
 select decrypted_secret into token from vault.decrypted_secrets where name='erp_calendar_job_token';if token is null then return null;end if;
 select net.http_post(url:='https://cszsxjsiwaaibrocibyd.supabase.co/functions/v1/erp-calendar-reminders',body:='{}'::jsonb,headers:=jsonb_build_object('Content-Type','application/json','X-ERP-Calendar-Job',token),timeout_milliseconds:=110000) into request_id;return request_id;
 end$$;
-- A már meglévő saját ERP-karbantartási igény dátumválasztási kapujának összehangolása.
do $guard$ declare definition text;needle text:='day:=nullif(p_command->>''day'','''')::date;';begin
 select pg_get_functiondef('erp_private.maint_prepare(uuid,uuid,uuid,uuid,text,jsonb,jsonb)'::regprocedure) into definition;
 if position(needle in definition)=0 then raise exception 'A saját karbantartási ellenőrző eltér a tesztelt változattól.';end if;
 definition:=replace(definition,needle,needle||'if p_role=''client'' and day is not null and nullif(current_setting(''erp.calendar_booking_request'',true),'''') is null and not coalesce((select (document->>''date_requests'')::boolean from erp.calendar_settings where organization_id=p_org),false) then raise exception ''Szabad dátumigényt az iroda jelenleg nem engedélyezett.'' using errcode=''42501'';end if;');execute definition;end $guard$;
do $context$ declare definition text;needle text:='return jsonb_build_object(''organization_id'',p_org';begin
 select pg_get_functiondef('erp_private.maint_scope(uuid,uuid,uuid,uuid,text)'::regprocedure) into definition;if position(needle in definition)=0 then raise exception 'A saját karbantartási kontextus eltér a tesztelt változattól.';end if;
 definition:=replace(definition,needle,'return jsonb_build_object(''date_requests'',coalesce((select (document->>''date_requests'')::boolean from erp.calendar_settings where organization_id=p_org),false),''organization_id'',p_org');execute definition;end $context$;
-- Közvetlen táblajog nincs. Az RPC-k kizárólag a saját ellenőrzött kiszolgálón át érhetők el.
do $$declare r record;begin
 for r in select n.nspname schema_name,c.relname table_name from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and (n.nspname='erp' and c.relname in('calendar_settings','calendar_catalog','daily_plans','daily_plan_versions','calendar_slots','calendar_blocks','calendar_booking_requests','calendar_events','calendar_notifications','calendar_push_subscriptions','calendar_reminders') or n.nspname='erp_private' and c.relname in('calendar_source_rows','calendar_import_runs','calendar_commands','calendar_reminder_deliveries')) loop
 execute format('alter table %I.%I enable row level security',r.schema_name,r.table_name);execute format('alter table %I.%I force row level security',r.schema_name,r.table_name);execute format('revoke all on %I.%I from public,anon,authenticated,service_role',r.schema_name,r.table_name);end loop;
 for r in select p.oid::regprocedure signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='erp_private' and p.proname like 'calendar_%' or n.nspname='public' and p.proname like 'erp_calendar_%' loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',r.signature);if r.nspname='public' then execute format('grant execute on function %s to service_role',r.signature);end if;end loop;
end$$;
commit;
